package com.masterclass.inventory.integration; import java.util.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.test.web.client.TestRestTemplate; import org.springframework.http.*; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.testcontainers.containers.MSSQLServerContainer; import org.testcontainers.junit.jupiter.*; import static org.assertj.core.api.Assertions.*;
@Testcontainers @SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) class ProductApiIntegrationTest { @Container static MSSQLServerContainer<?> sql=new MSSQLServerContainer<>("mcr.microsoft.com/mssql/server:2022-latest").acceptLicense(); @Autowired TestRestTemplate rest; @DynamicPropertySource static void props(DynamicPropertyRegistry r){ r.add("spring.datasource.url", sql::getJdbcUrl); r.add("spring.datasource.username", sql::getUsername); r.add("spring.datasource.password", sql::getPassword); r.add("spring.jpa.hibernate.ddl-auto", ()->"create-drop"); } @Test void productCrudSmoke(){ var api=rest.withBasicAuth("admin","admin123"); ResponseEntity<Map> cat=api.postForEntity("/api/v1/categories", Map.of("name","Smoke","description","integration test"), Map.class); assertThat(cat.getStatusCode()).isEqualTo(HttpStatus.CREATED); Long catId=((Number) cat.getBody().get("id")).longValue(); var product=new HashMap<String,Object>(Map.of("sku","SMK-001","name","Smoke Milk","categoryId",catId,"unitPrice",1.50,"currentStock",10,"reorderLevel",2,"status","ACTIVE")); ResponseEntity<Map> created=api.postForEntity("/api/v1/products", product, Map.class); assertThat(created.getStatusCode()).isEqualTo(HttpStatus.CREATED); assertThat(created.getBody().get("sku")).isEqualTo("SMK-001"); ResponseEntity<List> found=api.getForEntity("/api/v1/products?q=SMK-001", List.class); assertThat(found.getStatusCode()).isEqualTo(HttpStatus.OK); assertThat(found.getBody()).hasSize(1); } }
